def sum_even(nums: list[int]) -> int:
    s = 0
    for x in nums:
        if x % 2 == 0:
            s += x
    return s

def is_clean_palindrome(text: str) -> bool:
    cleaned = ''.join(c.lower() for c in text if c.isalnum())
    return cleaned == cleaned[::-1]

def two_sum(nums: list[int], target: int) -> list[int]:
    seen = {}
    for i, x in enumerate(nums):
        comp = target - x
        if comp in seen:
            return [seen[comp], i]
        seen[x] = i
    return []

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or interval[0] > merged[-1][1]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def first_occurrence(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    if left < len(nums) and nums[left] == target:
        return left
    return -1

def longest_unique_length(s: str) -> int:
    last_seen = {}
    max_len = 0
    left = 0
    for right, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        curr_len = right - left + 1
        if curr_len > max_len:
            max_len = curr_len
    return max_len

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

def min_cover(s: str, t: str) -> str:
    if not t:
        return ""
    from collections import defaultdict
    need = defaultdict(int)
    for c in t:
        need[c] += 1
    required = len(need)
    left = 0
    matched = 0
    window = defaultdict(int)
    min_len = float('inf')
    start = 0
    for right, c in enumerate(s):
        window[c] += 1
        if c in need and window[c] == need[c]:
            matched += 1
        while matched == required:
            if right - left + 1 < min_len:
                min_len = right - left + 1
                start = left
            left_c = s[left]
            if left_c in need:
                if window[left_c] == need[left_c]:
                    matched -= 1
                window[left_c] -= 1
            left += 1
    if min_len == float('inf'):
        return ""
    return s[start:start+min_len]

def count_in_range(nums: list[int], lo: int, hi: int) -> int:
    count = 0
    for x in nums:
        if lo <= x <= hi:
            count += 1
