def has_two_sum_sorted(nums: list[int], target: int) -> bool:
    n = len(nums)
    if n < 2:
        return False
    left, right = 0, n - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return True
        elif s < target:
            left += 1
        else:
            right -= 1
    return False

def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    cnt = [0] * 52
    for ch in s:
        if ch.isupper():
            cnt[ord(ch) - ord('A')] += 1
        else:
            cnt[26 + ord(ch) - ord('a')] += 1
    for ch in t:
        if ch.isupper():
            cnt[ord(ch) - ord('A')] -= 1
        else:
            cnt[26 + ord(ch) - ord('a')] -= 1
    return all(c == 0 for c in cnt)

def range_sums(nums: list[int], queries: list[tuple[int, int]]) -> list[int]:
    if not nums or not queries:
        return []
    n = len(nums)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + nums[i]
    res = []
    for l, r in queries:
        res.append(pref[r+1] - pref[l])
    return res

def atm_balance(ops: list[int]) -> int:
    balance = 0
    for op in ops:
        if op > 0:
            balance += op
        elif op < 0:
            if balance >= -op:
                balance += op
    return balance

def is_balanced(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        elif c in mapping:
            if not stack or stack.pop() != mapping[c]:
                return False
    return not stack

