def reverse_vowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    lst = list(s)
    i, j = 0, len(lst)-1
    while i < j:
        if lst[i] not in vowels:
            i += 1
        elif lst[j] not in vowels:
            j -= 1
        else:
            lst[i], lst[j] = lst[j], lst[i]
            i += 1
            j -= 1
    return ''.join(lst)

def is_symmetric(matrix: list[list[int]]) -> bool:
    n = len(matrix)
    if n == 0:
        return True
    for row in matrix:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

