def max_area(heights: list[int]) -> int:
    n = len(heights)
    if n < 2:
        return 0
    l, r = 0, n - 1
    max_a = 0
    while l < r:
        area = (r - l) * min(heights[l], heights[r])
        if area > max_a:
            max_a = area
        if heights[l] < heights[r]:
            l += 1
        else:
            r -= 1
    return max_a

def count_subarray_sum(nums: list[int], k: int) -> int:
    count = 0
    prefix_sum = 0
    freq = {0: 1}
    for num in nums:
        prefix_sum += num
        if prefix_sum - k in freq:
            count += freq[prefix_sum - k]
        freq[prefix_sum] = freq.get(prefix_sum, 0) + 1
    return count

def daily_warmer(temps: list[int]) -> list[int]:
    n = len(temps)
    ans = [0] * n
    stack = []
    for i in range(n):
        while stack and temps[i] > temps[stack[-1]]:
            idx = stack.pop()
            ans[idx] = i - idx
        stack.append(i)
    return ans

def fast_power(x: float, n: int) -> float:
    if n == 0:
        return 1.0
    if n < 0:
        return 1.0 / fast_power(x, -n)
    half = fast_power(x, n // 2)
    if n % 2 == 0:
        return half * half
    else:
        return half * half * x

def spiral_order(matrix: list[list[int]]) -> list[int]:
    if not matrix or not matrix[0]:
        return []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    res = []
    while top <= bottom and left <= right:
        for i in range(left, right + 1):
            res.append(matrix[top][i])
        top += 1
        if top <= bottom:
            for i in range(top, bottom + 1):
                res.append(matrix[i][right])
            right -= 1
        if top <= bottom and left <= right:
            for i in range(right, left - 1, -1):
                res.append(matrix[bottom][i])
            bottom -= 1
        if top <= bottom and left <= right:
            for i in range(bottom, top - 1, -1):
                res.append(matrix[i][left])
            left += 1
    return res

def jump_count(nums: list[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0
    jumps = 0
    cur_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + nums[i])
        if i == cur_end:
            jumps += 1
            cur_end = farthest
            if cur_end >= n - 1:
                break
    return jumps

def str_str(haystack: str, needle: str) -> int:
    if not needle:
        return 0
    m = len(needle)
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    n = len(haystack)
    i = 0
    j = 0
    while i < n:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == m:
                return i - j
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1

def max_sliding(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0 or k > len(nums):
        return []
    from collections import deque
    dq = deque()
    res = []
    for i, x in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] < x:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

def search_rotated(nums: list[int], target: int) -> int:
    n = len(nums)
    if n == 0:
        return -1
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def merge_sorted(a: list[int], b: list[int]) -> list[int]:
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res

import random

def kth_largest(nums: list[int], k: int) -> int:
    def select(arr, kk):
        if len(arr) == 1:
            return arr[0]
        pivot = random.choice(arr)
        greater = [x for x in arr if x > pivot]
        equal = [x for x in arr if x == pivot]
        less = [x for x in arr if x < pivot]
        if kk <= len(greater):
            return select(greater, kk)
        elif kk <= len(greater) + len(equal):
            return pivot
        else:
            return select(less, kk - len(greater) - len(equal))
    return select(nums, k)

def range_add_diff(n: int, ops: list[list[int]]) -> list[int]:
    if n == 0:
        return []
    diff = [0] * (n + 1)
    for l, r, v in ops:
        diff[l] += v
        diff[r + 1] -= v
    res = [0] * n
    cur = 0
    for i in range(n):
        cur += diff[i]
        res[i] = cur
    return res

