def is_valid_stack_sequence(pushed: list[int], popped: list[int]) -> bool:
    if len(pushed) != len(popped):
        return False
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return j == len(popped)

def min_cover_count(intervals: list[list[int]], s: int, t: int) -> int:
    if s >= t:
        return 0
    intervals.sort(key=lambda x: (x[0], -x[1]))
    cur = s
    ans = 0
    i = 0
    n = len(intervals)
    while cur < t:
        max_r = cur
        while i < n and intervals[i][0] <= cur:
            if intervals[i][1] > max_r:
                max_r = intervals[i][1]
            i += 1
        if max_r == cur:
            return -1
        cur = max_r
        ans += 1
    return ans

def min_palindrome_inserts(s: str) -> int:
    n = len(s)
    if n <= 1:
        return 0
    dp = [[0] * n for _ in range(n)]
    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = min(dp[i + 1][j], dp[i][j - 1]) + 1
    return dp[0][n - 1]

def three_sum_zero(nums: list[int]) -> list[list[int]]:
    if len(nums) < 3:
        return []
    nums.sort()
    res = []
    n = len(nums)
    for i in range(n - 2):
        if nums[i] > 0:
            break
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                res.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left+1]:
                    left += 1
                while left < right and nums[right] == nums[right-1]:
                    right -= 1
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    return res

def cycle_info(nexts: list[int]) -> list[int]:
    n = len(nexts)
    if n == 0:
        return [-1, 0]
    slow = 0
    fast = 0
    while True:
        if nexts[slow] == -1:
            return [-1, 0]
        slow = nexts[slow]
        if nexts[fast] == -1:
            return [-1, 0]
        fast = nexts[fast]
        if nexts[fast] == -1:
            return [-1, 0]
        fast = nexts[fast]
        if slow == fast:
            break
    slow = 0
    while slow != fast:
        slow = nexts[slow]
        fast = nexts[fast]
    entrance = slow
    length = 1
    cur = nexts[entrance]
    while cur != entrance:
        cur = nexts[cur]
        length += 1
    return [entrance, length]

def count_digit_range(lo: int, hi: int, d: int) -> int:
    def f(n: int, d: int) -> int:
        if n < 0:
            return 0
        total = 0
        factor = 1
        i = 0
        while True:
            higher = n // (factor * 10)
            current = (n // factor) % 10
            lower = n % factor
            if d == 0 and i > 0:
                if higher > 0:
                    total += (higher - 1) * factor
                    if current > 0:
                        total += factor
                    elif current == 0:
                        total += lower + 1
            else:
                total += higher * factor
                if current > d:
                    total += factor
                elif current == d:
                    total += lower + 1
            if higher == 0 and current == 0:
                break
            factor *= 10
            i += 1
        return total
    return f(hi, d) - f(lo - 1, d)

def max_overlap(events: list[list[int]]) -> int:
    events = [(s, e) for s, e in events if s < e]
    if not events:
        return 0
    evs = []
    for s, e in events:
        evs.append((s, 1))
        evs.append((e, -1))
    evs.sort(key=lambda x: (x[0], x[1]))
    cur = 0
    ans = 0
    for _, d in evs:
        cur += d
        if cur > ans:
            ans = cur
    return ans

def zigzag_levels(children: list[list[int]]) -> list[list[int]]:
    if not children:
        return []
    from collections import deque
    q = deque([0])
    res = []
    depth = 0
    while q:
        level_size = len(q)
        level_nodes = []
        for _ in range(level_size):
            node = q.popleft()
            level_nodes.append(node)
            for child in children[node]:
                q.append(child)
        if depth % 2 == 1:
            level_nodes.reverse()
        res.append(level_nodes)
        depth += 1
    return res

def lcs_lex_smallest(a: str, b: str) -> str:
    n, m = len(a), len(b)
    dp = [["" for _ in range(m+1)] for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            best = dp[i+1][j]
            if len(dp[i][j+1]) > len(best) or (len(dp[i][j+1]) == len(best) and dp[i][j+1] < best):
                best = dp[i][j+1]
            if a[i] == b[j]:
                cand = a[i] + dp[i+1][j+1]
                if len(cand) > len(best) or (len(cand) == len(best) and cand < best):
                    best = cand
            dp[i][j] = best
    return dp[0][0]

def min_merge_cost(stones: list[int]) -> int:
    n = len(stones)
    if n <= 1:
        return 0
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + stones[i]
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            total = pref[j+1] - pref[i]
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + total)
    return dp[0][n-1]

def min_cover_circular_len(s: str, t: str) -> int:
    if not t:
        return 0
    n = len(s)
    if n == 0:
        return -1
    s2 = s + s
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    missing = len(t)
    left = 0
    min_len = n + 1
    for right in range(2 * n):
        c = s2[right]
        if c in need:
            if need[c] > 0:
                missing -= 1
            need[c] -= 1
        while missing == 0 and left <= right:
            cur_len = right - left + 1
            if left < n and cur_len <= n:
                if cur_len < min_len:
                    min_len = cur_len
            c_left = s2[left]
            if c_left in need:
                if need[c_left] >= 0:
                    missing += 1
                need[c_left] += 1
            left += 1
    return min_len if min_len <= n else -1

def longest_k_palindrome(s: str, k: int) -> int:
    n = len(s)
    if n == 0:
        return 0
    dp = [[0]*n for _ in range(n)]
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            prev = 0 if i+1 > j-1 else dp[i+1][j-1]
            dp[i][j] = prev + (0 if s[i]==s[j] else 1)
    ans = 0
    for i in range(n):
        for j in range(i, n):
            if dp[i][j] <= k:
                ans = max(ans, j-i+1)
    return ans

def top_k_frequent(nums: list[int], k: int) -> list[int]:
    if k <= 0:
        return []
    freq_map = {}
    for num in nums:
        if num in freq_map:
            freq_map[num] += 1
        else:
            freq_map[num] = 1
    items = [(freq, num) for num, freq in freq_map.items()]
    d = len(items)
    m = min(k, d)
    heap = []
    def greater(a, b):
        if a[0] != b[0]:
            return a[0] > b[0]
        return a[1] < b[1]
    def sift_up(i):
        while i > 0:
            p = (i - 1) // 2
            if greater(heap[i], heap[p]):
                heap[i], heap[p] = heap[p], heap[i]
                i = p
            else:
                break
    def sift_down(i):
        n = len(heap)
        while True:
            l = 2 * i + 1
            r = 2 * i + 2
            largest = i
            if l < n and greater(heap[l], heap[largest]):
                largest = l
            if r < n and greater(heap[r], heap[largest]):
                largest = r
            if largest != i:
                heap[i], heap[largest] = heap[largest], heap[i]
                i = largest
            else:
                break
    def push(val):
        heap.append(val)
        sift_up(len(heap) - 1)
    def pop():
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            sift_down(0)
        return top
    for item in items:
        push(item)
    res = []
    for _ in range(m):
        freq, num = pop()
        res.append(num)
    return res

def knapsack_exact(weights: list[int], values: list[int], cap: int) -> int:
    dp = [-1] * (cap + 1)
    dp[0] = 0
    zero_val = 0
    for w, v in zip(weights, values):
        if w == 0:
            zero_val += v
        else:
            for j in range(cap, w - 1, -1):
                if dp[j - w] != -1:
                    cand = dp[j - w] + v
                    if cand > dp[j]:
                        dp[j] = cand
    if dp[cap] == -1:
        return -1
    return dp[cap] + zero_val

def edit_distance_costs(a: str, b: str, ci: int, cd: int, cs: int) -> int:
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i * cd
    for j in range(m + 1):
        dp[0][j] = j * ci
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if a[i-1] == b[j-1] else cs
            dp[i][j] = min(dp[i-1][j] + cd, dp[i][j-1] + ci, dp[i-1][j-1] + cost)
    return dp[n][m]

def max_profit_cooldown_fee(prices: list[int], fee: int) -> int:
    if not prices:
        return 0
    hold = -prices[0]
    sold = float('-inf')
    rest = 0
    for price in prices[1:]:
        hold, sold, rest = max(hold, rest - price), hold + price - fee, max(rest, sold)
    return max(0, sold, rest)

def min_spanning_cost(n: int, edges: list[list[int]]) -> int:
    if n <= 1:
        return 0
    edges.sort(key=lambda e: e[2])
    parent = list(range(n))
    size = [1] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True
    cost = 0
    cnt = 0
    for u, v, w in edges:
        if union(u, v):
            cost += w
            cnt += 1
            if cnt == n - 1:
                break
    return cost if cnt == n - 1 else -1

def min_max_split_sum(nums: list[int], k: int) -> int:
    if not nums:
        return 0
    left, right = max(nums), sum(nums)
    def can(x):
        cnt = 1
        s = 0
        for v in nums:
            if s + v > x:
                cnt += 1
                s = v
                if cnt > k:
                    return False
            else:
                s += v
        return True
    while left < right:
        mid = (left + right) // 2
        if can(mid):
            right = mid
        else:
            left = mid + 1
    return left

def count_submatrices_sum_eq(matrix: list[list[int]], target: int) -> int:
    if not matrix or not matrix[0]:
        return 0
    n = len(matrix)
    m = len(matrix[0])
    count = 0
    for top in range(n):
        col_sum = [0] * m
        for bottom in range(top, n):
            for j in range(m):
                col_sum[j] += matrix[bottom][j]
            prefix = 0
            freq = {0: 1}
            for val in col_sum:
                prefix += val
                count += freq.get(prefix - target, 0)
                freq[prefix] = freq.get(prefix, 0) + 1
    return count

def lex_topo_order(n: int, edges: list[list[int]]) -> list[int]:
    if n == 0:
        return []
    indeg = [0] * n
    adj = [[] for _ in range(n)]
    for u, v in edges:
        indeg[v] += 1
        adj[u].append(v)
    heap = []
    def push(x):
        heap.append(x)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) // 2
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p
    def pop():
        res = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = 2*i + 1
                r = 2*i + 2
                smallest = i
                if l < len(heap) and heap[l] < heap[smallest]:
                    smallest = l
                if r < len(heap) and heap[r] < heap[smallest]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return res
    for i in range(n):
        if indeg[i] == 0:
            push(i)
    res = []
    while heap:
        u = pop()
        res.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                push(v)
    if len(res) != n:
        return []
    return res

def count_digit_sum_divisible(n: int, k: int) -> int:
    digits = list(map(int, str(n)))
    dp = [[0]*k for _ in range(2)]
    dp[1][0] = 1
    for d_max in digits:
        ndp = [[0]*k for _ in range(2)]
        for tight in (0,1):
            for rem in range(k):
                if dp[tight][rem] == 0:
                    continue
                limit = d_max if tight else 9
                for d in range(limit+1):
                    new_tight = 1 if (tight and d == limit) else 0
                    new_rem = (rem + d) % k
                    ndp[new_tight][new_rem] += dp[tight][rem]
        dp = ndp
    return dp[0][0] + dp[1][0]

def tree_knapsack(weights: list[int], children: list[list[int]], k: int) -> int:
    n = len(weights)
    if n == 0:
        return 0 if k == 0 else -1
    INF = -10**15
    dp0 = [[INF] * (k + 1) for _ in range(n)]
    dp1 = [[INF] * (k + 1) for _ in range(n)]
    for u in range(n - 1, -1, -1):
        tmp0 = [INF] * (k + 1)
        tmp1 = [INF] * (k + 1)
        tmp0[0] = 0
        if k >= 1:
            tmp1[1] = weights[u]
        for v in children[u]:
            new0 = [INF] * (k + 1)
            new1 = [INF] * (k + 1)
            for i in range(k + 1):
                if tmp0[i] == INF:
                    continue
                for j in range(k + 1 - i):
                    val = max(dp0[v][j], dp1[v][j])
                    if val != INF:
                        if tmp0[i] + val > new0[i + j]:
                            new0[i + j] = tmp0[i] + val
            for i in range(k + 1):
                if tmp1[i] == INF:
                    continue
                for j in range(k + 1 - i):
                    val = dp0[v][j]
                    if val != INF:
                        if tmp1[i] + val > new1[i + j]:
                            new1[i + j] = tmp1[i] + val
            tmp0, tmp1 = new0, new1
        dp0[u] = tmp0
        dp1[u] = tmp1
    ans = max(dp0[0][k], dp1[0][k])
    return ans if ans >= 0 else -1

def tsp_min_path(dist: list[list[int]]) -> int:
    n = len(dist)
    if n <= 1:
        return 0
    INF = 10**9
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1 << n):
        for u in range(n):
            if not (mask >> u) & 1 or dp[mask][u] == INF:
                continue
            for v in range(n):
                if (mask >> v) & 1:
                    continue
                nxt = mask | (1 << v)
                nd = dp[mask][u] + dist[u][v]
                if nd < dp[nxt][v]:
                    dp[nxt][v] = nd
    return min(dp[(1 << n) - 1])

def count_interleavings(s1: str, s2: str, s3: str) -> int:
    n1, n2, n3 = len(s1), len(s2), len(s3)
    if n1 + n2 != n3:
        return 0
    dp = [0] * (n2 + 1)
    dp[0] = 1
    for i in range(n1 + 1):
        for j in range(n2 + 1):
            if i == 0 and j == 0:
                continue
            ways = 0
            if i > 0 and s1[i-1] == s3[i+j-1]:
                ways += dp[j]
            if j > 0 and s2[j-1] == s3[i+j-1]:
                ways += dp[j-1]
            dp[j] = ways
    return dp[n2]

def longest_bitonic_subsequence(nums: list[int]) -> int:
    from bisect import bisect_left
    if not nums:
        return 0
    n = len(nums)
    def lis_arr(arr):
        tails = []
        out = []
        for x in arr:
            i = bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
            out.append(i + 1)
        return out
    inc = lis_arr(nums)
    dec = lis_arr(nums[::-1])[::-1]
    return max(inc[i] + dec[i] - 1 for i in range(n))

def shortest_palindrome_append(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    t = s[::-1] + '#' + s
    m = len(t)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and t[i] != t[j]:
            j = pi[j-1]
        if t[i] == t[j]:
            j += 1
        pi[i] = j
    L = pi[-1]
    return s + s[:n-L][::-1]

def knapsack_2d(weights: list[int], volumes: list[int], values: list[int], cap_w: int, cap_v: int) -> int:
    n = len(weights)
    dp = [[0] * (cap_v + 1) for _ in range(cap_w + 1)]
    for i in range(n):
        w = weights[i]
        v = volumes[i]
        val = values[i]
        for j in range(cap_w, w - 1, -1):
            for k in range(cap_v, v - 1, -1):
                dp[j][k] = max(dp[j][k], dp[j - w][k - v] + val)
    return dp[cap_w][cap_v]

def min_concat_number(nums: list[int]) -> str:
    if not nums:
        return ''
    strs = [str(x) for x in nums]
    n = len(strs)
    for i in range(n):
        for j in range(0, n - i - 1):
            if strs[j] + strs[j+1] > strs[j+1] + strs[j]:
                strs[j], strs[j+1] = strs[j+1], strs[j]
    result = ''.join(strs)
    if result and all(c == '0' for c in result):
        return '0'
    return result

def min_rooms_with_gap(intervals: list[list[int]], gap: int) -> int:
    class MinHeap:
        def __init__(self):
            self.h = []
        def push(self, x):
            self.h.append(x)
            i = len(self.h)-1
            while i > 0:
                p = (i-1)//2
                if self.h[p] <= self.h[i]:
                    break
                self.h[p], self.h[i] = self.h[i], self.h[p]
                i = p
        def pop(self):
            if len(self.h) == 1:
                return self.h.pop()
            top = self.h[0]
            self.h[0] = self.h.pop()
            i = 0
            n = len(self.h)
            while True:
                l = 2*i+1
                r = 2*i+2
                smallest = i
                if l < n and self.h[l] < self.h[smallest]:
                    smallest = l
                if r < n and self.h[r] < self.h[smallest]:
                    smallest = r
                if smallest == i:
                    break
                self.h[i], self.h[smallest] = self.h[smallest], self.h[i]
                i = smallest
            return top
        def peek(self):
            return self.h[0]
        def size(self):
            return len(self.h)
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[0])
    heap = MinHeap()
    for s, e in intervals:
        if heap.size() > 0 and heap.peek() <= s:
            heap.pop()
        heap.push(e + gap)
    return heap.size()

def stone_game_diff(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            best = nums[i] - dp[i+1][j]
            best = max(best, nums[j] - dp[i][j-1])
            if i + 2 <= j:
                best = max(best, nums[i] + nums[i+1] - dp[i+2][j])
            else:
                best = max(best, nums[i] + nums[i+1])
            if i <= j - 2:
                best = max(best, nums[j] + nums[j-1] - dp[i][j-2])
            else:
                best = max(best, nums[j] + nums[j-1])
            dp[i][j] = best
    return dp[0][n-1]

def min_spanning_tree_cost(n: int, edges: list[list[int]]) -> int:
    if n <= 1:
        return 0
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    filtered = [ (u, v, w) for u, v, w in edges if u != v ]
    filtered.sort(key=lambda e: e[2])
    total = 0
    count = 0
    for u, v, w in filtered:
        if union(u, v):
            total += w
            count += 1
            if count == n - 1:
                break
    return total if count == n - 1 else -1

def shortest_path_cost(n: int, edges: list[list[int]], src: int, dst: int) -> int:
    if src == dst:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    class MinHeap:
        def __init__(self):
            self.data = []
        def push(self, item):
            self.data.append(item)
            self._sift_up(len(self.data)-1)
        def pop(self):
            if not self.data:
                return None
            res = self.data[0]
            last = self.data.pop()
            if self.data:
                self.data[0] = last
                self._sift_down(0)
            return res
        def _sift_up(self, i):
            while i > 0:
                p = (i-1)//2
                if self.data[i][0] < self.data[p][0]:
                    self.data[i], self.data[p] = self.data[p], self.data[i]
                    i = p
                else:
                    break
        def _sift_down(self, i):
            n = len(self.data)
            while True:
                l = 2*i+1
                r = 2*i+2
                smallest = i
                if l < n and self.data[l][0] < self.data[smallest][0]:
                    smallest = l
                if r < n and self.data[r][0] < self.data[smallest][0]:
                    smallest = r
                if smallest != i:
                    self.data[i], self.data[smallest] = self.data[smallest], self.data[i]
                    i = smallest
                else:
                    break
        def is_empty(self):
            return len(self.data) == 0
    INF = 10**18
    dist = [INF] * n
    dist[src] = 0
    heap = MinHeap()
    heap.push((0, src))
    while not heap.is_empty():
        d, u = heap.pop()
        if d > dist[u]:
            continue
        if u == dst:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heap.push((nd, v))
    return -1 if dist[dst] == INF else dist[dst]

def feasible_binary_array(n: int, constraints: list[list[int]]) -> bool:
    if n == 0:
        return True
    V = n + 2
    src = n + 1
    edges = []
    for i in range(n):
        edges.append((i, i+1, 0))
        edges.append((i+1, i, -1))
    for l, r, lo, hi in constraints:
        edges.append((l, r+1, lo))
        edges.append((r+1, l, -hi))
    for i in range(n+1):
        edges.append((src, i, 0))
    dist = [-float('inf')] * V
    dist[src] = 0
    for _ in range(V-1):
        for u, v, w in edges:
            if dist[u] != -float('inf') and dist[v] < dist[u] + w:
                dist[v] = dist[u] + w
    for u, v, w in edges:
        if dist[u] != -float('inf') and dist[v] < dist[u] + w:
            return False
    return True
